import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md","lastUpdated":1789979194000}'),s={name:"en/faq.md"};function i(n,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="why-does-the-footer-still-show-komari-ds" tabindex="-1">Why does the footer still show komari-ds? <a class="header-anchor" href="#why-does-the-footer-still-show-komari-ds" aria-label="Permalink to &quot;Why does the footer still show komari-ds?&quot;">​</a></h2><p>Install the latest theme package and force-refresh the browser. An older theme or Service Worker may still be cached. The internal theme ID stays <code>komari-ds</code>; the public footer is Komari Next Pro.</p><h2 id="why-is-an-ip-probe-only-partially-complete" tabindex="-1">Why is an IP probe only partially complete? <a class="header-anchor" href="#why-is-an-ip-probe-only-partially-complete" aria-label="Permalink to &quot;Why is an IP probe only partially complete?&quot;">​</a></h2><p>IPv4, IPv6 and quality lookups have separate results. Successful data is retained when another part fails. DNS failures, timeouts, rate limits and missing configuration are reported explicitly.</p><h2 id="are-ip-reference-scores-actual-reputation-measurements" tabindex="-1">Are IP reference scores actual reputation measurements? <a class="header-anchor" href="#are-ip-reference-scores-actual-reputation-measurements" aria-label="Permalink to &quot;Are IP reference scores actual reputation measurements?&quot;">​</a></h2><p>No. They are documented deterministic heuristics based on metadata and network classification. Unknown fields do not create evidence. Actual provider flags remain in a separate view.</p><h2 id="does-a-successful-http-response-prove-streaming-unlock" tabindex="-1">Does a successful HTTP response prove streaming unlock? <a class="header-anchor" href="#does-a-successful-http-response-prove-streaming-unlock" aria-label="Permalink to &quot;Does a successful HTTP response prove streaming unlock?&quot;">​</a></h2><p>No. Accounts, subscriptions, regions and individual content may have additional restrictions. The panel preserves response evidence rather than declaring every HTTP 200 fully unlocked.</p><h2 id="what-does-a-red-github-deployment-mean" tabindex="-1">What does a red GitHub deployment mean? <a class="header-anchor" href="#what-does-a-red-github-deployment-mean" aria-label="Permalink to &quot;What does a red GitHub deployment mean?&quot;">​</a></h2><p>That hosting deployment failed. Its status is separate from unit tests or a successful theme Release. Check the deployment logs, project root, build command and output directory. Old failure records remain historical records.</p><h2 id="can-i-deploy-the-monitoring-theme-itself-as-the-project-website" tabindex="-1">Can I deploy the monitoring theme itself as the project website? <a class="header-anchor" href="#can-i-deploy-the-monitoring-theme-itself-as-the-project-website" aria-label="Permalink to &quot;Can I deploy the monitoring theme itself as the project website?&quot;">​</a></h2><p>This repository&#39;s Vercel entry builds the documentation website. Install the monitoring theme inside Komari so its API requests have the correct backend. The documentation site does not access production monitoring data.</p>',13)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
